type VMSpecSerialConsole string

// VMSpecDisk Disk attached to a VM. Field semantics match the Control
// Plane's `VmDisk` / `VMCreateDiskSpec` exactly so a disk row
// round-trips through the contract without translation. The
// agent never sees the CP-side `storage_pool_id` UUID — the CP
// resolves it to `storage_pool_path` (an absolute filesystem
// path on this node) before sending the spec.
type VMSpecDisk struct {
	BootOrder *int                 `json:"boot_order,omitempty"`
	Bus       VMSpecDiskBus        `json:"bus"`
	CacheMode *VMSpecDiskCacheMode `json:"cache_mode,omitempty"`

	// DeviceOrder Position on the VM's disk bus; also boot-order tie-breaker.
	DeviceOrder int                `json:"device_order"`
	Discard     *VMSpecDiskDiscard `json:"discard,omitempty"`
	Format      VMSpecDiskFormat   `json:"format"`
	ReadOnly    *bool              `json:"read_only,omitempty"`
	SizeGib     int                `json:"size_gib"`

	// Source Disk image origin. The `kind` discriminates: when `image`,
	// `image_url`, `checksum_sha256` and `image_format` are
	// required (the VM is self-describing; the agent materializes the
	// image into the destination pool's cache on first use). When
	// `blank`, all three must be absent - the agent allocates an
	// empty image of `size_gib` instead. When `snapshot`,
	// `snapshot_sha256` is required and the agent clones the
	// content-addressed snapshot blob at
	// `{poolRoot}/snapshots/{snapshot_sha256}.qcow2` into the disk
	// (recreate-from-snapshot); `image_url` must be absent. The CP
	// resolves the snapshot manifest (ordered disk digests) before
	// send, so the agent never needs Control-Plane store access.
	Source VMSpecDiskSource `json:"source"`

	// StoragePoolID CP-side pool id, included as a label so the agent can
	// tag logs / metrics. Not used for any path lookup.
	StoragePoolID *openapi_types.UUID `json:"storage_pool_id,omitempty"`

	// StoragePoolPath Absolute filesystem path of the storage pool that backs
	// this disk on this node. The CP picks the pool (or
	// honours the user's pin) and resolves it before send.
	StoragePoolPath string `json:"storage_pool_path"`
}

// VMSpecDiskBus defines model for VMSpecDisk.Bus.
type VMSpecDiskBus string

// VMSpecDiskCacheMode defines model for VMSpecDisk.CacheMode.
type VMSpecDiskCacheMode string

